#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Cron jobok auto-újrapin-elése providerváltás érzékelésekor.
A drift_skip hibák zöme ebből ered: amikor a provider vált,
a régi pin-elt cron jobok elavulttá válnak és drift_skip hibát okoznak.
Ez a modul érzékeli a providerváltást és automatikusan újra-pin-eli
az összes aktív cron jobot az új providerre.
"""

import json
import time
import hashlib
import logging
import threading
from dataclasses import dataclass, field, asdict
from enum import Enum
from typing import Optional, Dict, List, Callable, Any
from datetime import datetime, timezone
from pathlib import Path

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s"
)
logger = logging.getLogger("cron_repin")


class JobStatus(Enum):
    PINNED = "pinned"
    DRIFT_SKIP = "drift_skip"
    REPINNED = "repinned"
    RUNNING = "running"
    COMPLETED = "completed"
    FAILED = "failed"


class ProviderType(Enum):
    OPENAI = "openai"
    ANTHROPIC = "anthropic"
    LOCAL = "local"
    AZURE = "azure"


@dataclass
class ProviderInfo:
    """Represents a provider configuration at a point in time."""
    provider_type: ProviderType
    model: str
    endpoint: str
    api_key_hash: str  # hash only, never store raw key
    config_hash: str = ""

    def __post_init__(self):
        if not self.config_hash:
            raw = f"{self.provider_type.value}:{self.model}:{self.endpoint}:{self.api_key_hash}"
            self.config_hash = hashlib.sha256(raw.encode()).hexdigest()[:16]

    def __eq__(self, other):
        if not isinstance(other, ProviderInfo):
            return False
        return self.config_hash == other.config_hash

    def __hash__(self):
        return hash(self.config_hash)


@dataclass
class CronJob:
    """A cron job that is pinned to a specific provider."""
    job_id: str
    name: str
    schedule: str  # cron expression like "*/5 * * * *"
    task_handler: str  # name of the handler function
    pinned_provider: Optional[ProviderInfo] = None
    status: JobStatus = JobStatus.PINNED
    last_run: Optional[float] = None
    last_provider_hash: str = ""
    repin_count: int = 0
    drift_skip_count: int = 0
    metadata: Dict[str, Any] = field(default_factory=dict)

    def is_drifted(self, current_provider: ProviderInfo) -> bool:
        """Check if this job's pinned provider differs from the current one."""
        if self.pinned_provider is None:
            return True
        return self.pinned_provider.config_hash != current_provider.config_hash

    def repin(self, new_provider: ProviderInfo) -> None:
        """Re-pin this job to a new provider."""
        old_hash = self.last_provider_hash
        self.pinned_provider = new_provider
        self.last_provider_hash = new_provider.config_hash
        self.status = JobStatus.REPINNED
        self.repin_count += 1
        logger.info(
            "Job '%s' (id=%s) re-pinned from %s to %s (repin #%d)",
            self.name, self.job_id, old_hash[:8] if old_hash else "none",
            new_provider.config_hash[:8], self.repin_count
        )


class ProviderRegistry:
    """
    Tracks the current provider and notifies listeners on change.
    Simulates the A2A Mesh provider switching mechanism.
    """
    def __init__(self, initial_provider: ProviderInfo):
        self._current: ProviderInfo = initial_provider
        self._lock = threading.RLock()
        self._listeners: List[Callable[[ProviderInfo, ProviderInfo], None]] = []
        self._history: List[tuple] = [(time.time(), initial_provider)]

    @property
    def current(self) -> ProviderInfo:
        with self._lock:
            return self._current

    def register_listener(self, listener: Callable[[ProviderInfo, ProviderInfo], None]):
        with self._lock:
            self._listeners.append(listener)

    def switch_provider(self, new_provider: ProviderInfo) -> bool:
        """Switch to a new provider. Returns True if changed, False if same."""
        with self._lock:
            if new_provider.config_hash == self._current.config_hash:
                logger.debug("Provider switch requested but no change (hash=%s)", new_provider.config_hash[:8])
                return False
            old = self._current
            self._current = new_provider
            self._history.append((time.time(), new_provider))
            logger.info(
                "Provider switched: %s/%s -> %s/%s",
                old.provider_type.value, old.model,
                new_provider.provider_type.value, new_provider.model
            )
            listeners = list(self._listeners)
        for listener in listeners:
            try:
                listener(old, new_provider)
            except Exception as e:
                logger.error("Provider change listener error: %s", e)
        return True

    def history(self) -> List[tuple]:
        with self._lock:
            return list(self._history)


class CronRepinManager:
    """
    Manages cron jobs and automatically re-pins them when the provider changes.
    This prevents drift_skip errors that occur when a job's pinned provider
    no longer matches the active provider.
    """
    def __init__(self, provider_registry: ProviderRegistry, state_file: Optional[Path] = None):
        self.registry = provider_registry
        self.jobs: Dict[str, CronJob] = {}
        self._lock = threading.RLock()
        self.state_file = state_file
        self._stop_event = threading.Event()
        self._monitor_thread: Optional[threading.Thread] = None
        self.repin_events: List[Dict] = []
        self.drift_skip_prevented: int = 0

        # Register as listener for provider changes
        self.registry.register_listener(self._on_provider_change)

        # Load persisted state if available
        if self.state_file and self.state_file.exists():
            self._load_state()

    def register_job(self, job: CronJob) -> None:
        """Register a new cron job, pinning it to the current provider."""
        with self._lock:
            if job.pinned_provider is None:
                job.pinned_provider = self.registry.current
                job.last_provider_hash = self.registry.current.config_hash
            self.jobs[job.job_id] = job
            logger.info("Registered cron job '%s' (id=%s) pinned to %s/%s",
                        job.name, job.job_id,
                        job.pinned_provider.provider_type.value,
                        job.pinned_provider.model)
        self._save_state()

    def unregister_job(self, job_id: str) -> bool:
        with self._lock:
            if job_id in self.jobs:
                del self.jobs[job_id]
                self._save_state()
                return True
            return False

    def _on_provider_change(self, old_provider: ProviderInfo, new_provider: ProviderInfo) -> None:
        """Called when the provider changes. Re-pins all active jobs."""
        logger.info("Provider change detected — initiating auto-repin for all cron jobs")
        with self._lock:
            jobs_to_repin = [
                job for job in self.jobs.values()
                if job.status in (JobStatus.PINNED, JobStatus.COMPLETED, JobStatus.REPINNED, JobStatus.DRIFT_SKIP)
            ]
        repinned = 0
        skipped = 0
        for job in jobs_to_repin:
            if job.is_drifted(new_provider):
                old_status = job.status
                job.repin(new_provider)
                repinned += 1
                self.repin_events.append({
                    "timestamp": datetime.now(timezone.utc).isoformat(),
                    "job_id": job.job_id,
                    "job_name": job.name,
                    "old_provider_hash": old_provider.config_hash,
                    "new_provider_hash": new_provider.config_hash,
                    "old_status": old_status.value,
                })
                if old_status == JobStatus.DRIFT_SKIP:
                    self.drift_skip_prevented += 1
            else:
                skipped += 1
        logger.info("Auto-repin complete: %d re-pinned, %d already aligned, %d drift_skip prevented",
                    repinned, skipped, self.drift_skip_prevented)
        self._save_state()

    def execute_job(self, job_id: str, handler: Optional[Callable[[CronJob, ProviderInfo], Any]] = None) -> Dict:
        """
        Execute a cron job. If the job's pinned provider has drifted,
        it would normally cause a drift_skip — but we auto-repin first.
        """
        with self._lock:
            job = self.jobs.get(job_id)
        if job is None:
            return {"success": False, "error": f"Job {job_id} not found"}

        current = self.registry.current

        # Check for drift before execution
        if job.is_drifted(current):
            # Auto-repin to prevent drift_skip
            logger.warning(
                "Job '%s' drifted from current provider during execution — auto-repinning",
                job.name
            )
            job.repin(current)
            self.drift_skip_prevented += 1
            self._save_state()

        # Execute
        job.status = JobStatus.RUNNING
        start = time.time()
        result = {"success": True, "job_id": job_id, "started_at": start}

        try:
            if handler:
                handler_result = handler(job, current)
                result["handler_result"] = handler_result
            else:
                # Simulated execution
                result["handler_result"] = f"executed on {current.provider_type.value}/{current.model}"
            job.status = JobStatus.COMPLETED
            job.last_run = time.time()
        except Exception as e:
            job.status = JobStatus.FAILED
            result["success"] = False
            result["error"] = str(e)
            logger.error("Job '%s' execution failed: %s", job.name, e)

        result["duration"] = time.time() - start
        result["status"] = job.status.value
        self._save_state()
        return result

    def check_drift(self) -> List[Dict]:
        """Check all jobs for drift without executing them."""
        current = self.registry.current
        drifted = []
        with self._lock:
            for job in self.jobs.values():
                if job.is_drifted(current):
                    drifted.append({
                        "job_id": job.job_id,
                        "job_name": job.name,
                        "pinned_hash": job.pinned_provider.config_hash if job.pinned_provider else "none",
                        "current_hash": current.config_hash,
                        "status": job.status.value,
                    })
                    if job.status != JobStatus.DRIFT_SKIP:
                        job.status = JobStatus.DRIFT_SKIP
                        job.drift_skip_count += 1
        return drifted

    def start_monitor(self, interval: float = 2.0) -> None:
        """Start a background thread that periodically checks for drift."""
        def _monitor():
            logger.info("Drift monitor started (interval=%.1fs)", interval)
            while not self._stop_event.is_set():
                drifted = self.check_drift()
                if drifted:
                    # Auto-repin drifted jobs
                    current = self.registry.current
                    for d in drifted:
                        with self._lock:
                            job = self.jobs.get(d["job_id"])
                        if job and job.is_drifted(current):
                            job.repin(current)
                            self.drift_skip_prevented += 1
                    self._save_state()
                self._stop_event.wait(interval)
            logger.info("Drift monitor stopped")

        self._stop_event.clear()
        self._monitor_thread = threading.Thread(target=_monitor, daemon=True, name="drift-monitor")
        self._monitor_thread.start()

    def stop_monitor(self) -> None:
        self._stop_event.set()
        if self._monitor_thread:
            self._monitor_thread.join(timeout=5.0)

    def _save_state(self) -> None:
        if not self.state_file:
            return
        try:
            state = {
                "jobs": {},
                "repin_events": self.repin_events[-100:],
                "drift_skip_prevented": self.drift_skip_prevented,
            }
            for jid, job in self.jobs.items():
                state["jobs"][jid] = {
                    "job_id": job.job_id,
                    "name": job.name,
                    "schedule": job.schedule,
                    "task_handler": job.task_handler,
                    "status": job.status.value,
                    "last_run": job.last_run,
                    "last_provider_hash": job.last_provider_hash,
                    "repin_count": job.repin_count,
                    "drift_skip_count": job.drift_skip_count,
                    "pinned_provider": {
                        "provider_type": job.pinned_provider.provider_type.value,
                        "model": job.pinned_provider.model,
                        "endpoint": job.pinned_provider.endpoint,
                        "api_key_hash": job.pinned_provider.api_key_hash,
                        "config_hash": job.pinned_provider.config_hash,
                    } if job.pinned_provider else None,
                    "metadata": job.metadata,
                }
            self.state_file.parent.mkdir(parents=True, exist_ok=True)
            self.state_file.write_text(json.dumps(state, indent=2, default=str))
        except Exception as e:
            logger.error("Failed to save state: %s", e)

    def _load_state(self) -> None:
        try:
            state = json.loads(self.state_file.read_text())
            for jid, jdata in state.get("jobs", {}).items():
                pinfo = None
                if jdata.get("pinned_provider"):
                    p = jdata["pinned_provider"]
                    pinfo = ProviderInfo(
                        provider_type=ProviderType(p["provider_type"]),
                        model=p["model"],
                        endpoint=p["endpoint"],
                        api_key_hash=p["api_key_hash"],
                        config_hash=p.get("config_hash", ""),
                    )
                job = CronJob(
                    job_id=jdata["job_id"],
                    name=jdata["name"],
                    schedule=jdata["schedule"],
                    task_handler=jdata["task_handler"],
                    pinned_provider=pinfo,
                    status=JobStatus(jdata["status"]),
                    last_run=jdata.get("last_run"),
                    last_provider_hash=jdata.get("last_provider_hash", ""),
                    repin_count=jdata.get("repin_count", 0),
                    drift_skip_count=jdata.get("drift_skip_count", 0),
                    metadata=jdata.get("metadata", {}),
                )
                self.jobs[jid] = job
            self.repin_events = state.get("repin_events", [])
            self.drift_skip_prevented = state.get("drift_skip_prevented", 0)
            logger.info("Loaded %d jobs from state file", len(self.jobs))
        except Exception as e:
            logger.error("Failed to load state: %s", e)

    def get_stats(self) -> Dict:
        with self._lock:
            return {
                "total_jobs": len(self.jobs),
                "repin_events": len(self.repin_events),
                "drift_skip_prevented": self.drift_skip_prevented,
                "provider_history": len(self.registry.history()),
                "jobs": [
                    {
                        "job_id": j.job_id,
                        "name": j.name,
                        "status": j.status.value,
                        "repin_count": j.repin_count,
                        "drift_skip_count": j.drift_skip_count,
                        "pinned_provider": j.pinned_provider.provider_type.value if j.pinned_provider else "none",
                    }
                    for j in self.jobs.values()
                ],
            }


def demo_handler(job: CronJob, provider: ProviderInfo) -> str:
    """Sample task handler for demonstration."""
    return f"[{job.name}] Task executed on {provider.provider_type.value}/{provider.model} at {datetime.now(timezone.utc).isoformat()}"


def main():
    """
    Demonstration: shows auto-repinning when provider changes.
    Simulates the scenario where drift_skip errors would normally occur.
    """
    print("=" * 70)
    print("A2A Mesh — Cron Auto-Repin on Provider Change")
    print("Prevents drift_skip errors caused by provider switching")
    print("=" * 70)

    state_file = Path("./.cron_repin_state.json")
    if state_file.exists():
        state_file.unlink()

    # Initial provider
    initial_provider = ProviderInfo(
        provider_type=ProviderType.OPENAI,
        model="gpt-4o",
        endpoint="https://api.openai.com/v1",
        api_key_hash=hashlib.sha256(b"sk-demo-key-1").hexdigest()[:16],
    )

    registry = ProviderRegistry(initial_provider)
    manager = CronRepinManager(registry, state_file=state_file)

    # Register some cron jobs
    jobs = [
        CronJob(
            job_id="cron-embedding-sync",
            name="Qdrant Embedding Sync",
            schedule="*/5 * * * *",
            task_handler="sync_embeddings",
            metadata={"queue": "embedding", "priority": "high"},
        ),
        CronJob(
            job_id="cron-keepalive",
            name="Mesh Keepalive Ping",
            schedule="*/1 * * * *",
            task_handler="send_keepalive",
            metadata={"queue": "mesh", "priority": "low"},
        ),
        CronJob(
            job_id="cron-dedup-check",
            name="Content Hash Dedup Check",
            schedule="*/10 * * * *",
            task_handler="dedup_check",
            metadata={"queue": "a2a", "priority": "medium"},
        ),
        CronJob(
            job_id="cron-health-check",
            name="Agent Health Check",
            schedule="*/3 * * * *",
            task_handler="health_check",
            metadata={"queue": "monitor", "priority": "medium"},
        ),
    ]

    for job in jobs:
        manager.register_job(job)

    print("\n--- Initial state ---")
    stats = manager.get_stats()
    print(json.dumps(stats, indent=2))

    # Execute a job on the initial provider
    print("\n--- Executing 'Qdrant Embedding Sync' on initial provider ---")
    result = manager.execute_job("cron-embedding-sync", handler=demo_handler)
    print(json.dumps(result, indent=2))

    # Start the drift monitor
    manager.start_monitor(interval=1.0)

    # Simulate provider switch 1: OpenAI -> Anthropic
    print("\n--- Simulating provider switch: OpenAI -> Anthropic ---")
    new_provider_1 = ProviderInfo(
        provider_type=ProviderType.ANTHROPIC,
        model="claude-sonnet-4-20250514",
        endpoint="https://api.anthropic.com/v1",
        api_key_hash=hashlib.sha256(b"sk-ant-demo-key-2").hexdigest()[:16],
    )
    registry.switch_provider(new_provider_1)
    time.sleep(1.5)  # let monitor catch up

    # Execute a job — should be auto-repinned, no drift_skip
    print("\n--- Executing 'Mesh Keepalive Ping' after provider switch ---")
    result = manager.execute_job("cron-keepalive", handler=demo_handler)
    print(json.dumps(result, indent=2))

    # Simulate provider switch 2: Anthropic -> Local
    print("\n--- Simulating provider switch: Anthropic -> Local Ollama ---")
    new_provider_2 = ProviderInfo(
        provider_type=ProviderType.LOCAL,
        model="llama3.3:70b",
        endpoint="http://localhost:11434",
        api_key_hash=hashlib.sha256(b"local-no-key").hexdigest()[:16],
    )
    registry.switch_provider(new_provider_2)
    time.sleep(1.5)

    # Simulate provider switch 3: Local -> Azure
    print("\n--- Simulating provider switch: Local -> Azure OpenAI ---")
    new_provider_3 = ProviderInfo(
        provider_type=ProviderType.AZURE,
        model="gpt-4o",
        endpoint="https://my-deployment.openai.azure.com",
        api_key_hash=hashlib.sha256(b"azure-demo-key-4").hexdigest()[:16],
    )
    registry.switch_provider(new_provider_3)
    time.sleep(1.5)

    # Execute all jobs
    print("\n--- Executing all jobs after multiple provider switches ---")
    for job_id in manager.jobs:
        result = manager.execute_job(job_id, handler=demo_handler)
        print(f"  {result.get('job_id')}: {result['status']} — {result.get('handler_result', '')}")

    # Stop monitor
    manager.stop_monitor()

    # Final stats
    print("\n--- Final statistics ---")
    final_stats = manager.get_stats()
    print(json.dumps(final_stats, indent=2))

    print(f"\n--- Repin events ({len(manager.repin_events)} total) ---")
    for event in manager.repin_events:
        print(f"  [{event['timestamp']}] {event['job_name']}: "
              f"{event['old_provider_hash'][:8]} -> {event['new_provider_hash'][:8]} "
              f"(was {event['old_status']})")

    print(f"\nDrift-skip errors prevented: {manager.drift_skip_prevented}")
    print(f"Provider switches: {len(registry.history())}")
    print(f"State persisted to: {state_file.resolve()}")

    # Verify state persistence by reloading
    print("\n--- Verifying state persistence (reload) ---")
    registry2 = ProviderRegistry(initial_provider)
    manager2 = CronRepinManager(registry2, state_file=state_file)
    print(f"Reloaded {len(manager2.jobs)} jobs, "
          f"{len(manager2.repin_events)} repin events, "
          f"{manager2.drift_skip_prevented} drift_skip prevented")

    # Cleanup
    if state_file.exists():
        state_file.unlink()
        print(f"\nCleaned up state file: {state_file}")

    print("\n" + "=" * 70)
    print("Demo complete — all cron jobs auto-repinned on provider changes")
    print("No drift_skip errors occurred thanks to auto-repin mechanism")
    print("=" * 70)


if __name__ == "__main__":
    main()